class Solution {
  public String encode(String s) {
    int n = s.length();
    String[][] dp = new String[n][n]; // dp[i][j]: shortest encoding of s[i..j]
    for (int len = 1; len <= n; len++) {
      for (int i = 0; i + len <= n; i++) {
        int j = i + len - 1;
        String sub = s.substring(i, j + 1);
        dp[i][j] = sub;
        if (len < 5) continue; // encoding can only help from length 5 on
        for (int k = i; k < j; k++)
          if (dp[i][k].length() + dp[k + 1][j].length() < dp[i][j].length()) dp[i][j] = dp[i][k] + dp[k + 1][j];
        // smallest repeating unit: first reappearance of sub inside sub + sub
        int p = (sub + sub).indexOf(sub, 1);
        if (p < sub.length()) {
          String enc = (sub.length() / p) + "[" + dp[i][i + p - 1] + "]";
          if (enc.length() < dp[i][j].length()) dp[i][j] = enc;
        }
      }
    }
    return dp[0][n - 1];
  }
}
